INSERT INTO `timesheets` (`id`, `unique_id`, `month`, `year`, `total_hours`, `notes`, `created_at`, `updated_at`) VALUES
(2, '5huxNFCA', 'July', '2024', 1860.00, ' <ul>\n                                <li>If you do not see your client in the client list. Please click on Add Client and add a client</li>\n                                <li>Please export this timesheet, export and save it. Use this link <a href=\"https://app.smartsheet.com/b/form/eb23234e2bb2463c9e0bb4215f018ee0\" target=\"_blank\">https://app.smartsheet.com/b/form/eb23234e2bb2463c9e0bb4215f018ee0</a> <br/>and upload the timesheet here with total hours and details.</li>\n                            </ul>', '2024-07-23 04:32:20', '2025-04-04 23:15:49'),
(3, 'KCPGcy29', 'August', '2024', 2218.25, '<ol>\r\n	<li>\r\n		If your client isn&#39;t listed, please click on &#39;Add Client&#39; to include them.</li>\r\n	<li>\r\n		After filling in your timesheet, export it by clicking on &#39;Export Timesheet,&#39; save the file to your desktop,</li>\r\n	<li>\r\n		Upload it to the following link with the total hours and other required details:&nbsp;<a href=\"https://app.smartsheet.com/b/form/18aaafae8b124ba2b7aec315797ce800\">https://app.smartsheet.com/b/form/18aaafae8b124ba2b7aec315797ce800</a></li>\r\n</ol>', '2024-08-14 19:35:04', '2025-04-04 02:00:57'),
(4, 'c3LLjmUv', 'September', '2024', 2006.75, '<ol>\r\n	<li>\r\n		If your client isn&#39;t listed, please click on &#39;Add Client&#39; to include them.</li>\r\n	<li>\r\n		After filling in your timesheet, export it by clicking on &#39;Export Timesheet,&#39; save the file to your desktop,</li>\r\n	<li>\r\n		Upload it to the following link with the total hours and other required details:&nbsp;https://app.smartsheet.com/b/form/beb38374496849cc98fa7a6979821873</li>\r\n</ol>', '2024-09-19 18:56:52', '2025-04-04 02:07:21'),
(5, '1PZkiZc0', 'October', '2024', 2447.25, '<ol>\r\n	<li>\r\n		If your client isn&#39;t listed, please click on &#39;Add Client&#39; to include them.</li>\r\n	<li>\r\n		After filling in your timesheet, export it by clicking on &#39;Export Timesheet,&#39; save the file to your desktop,</li>\r\n	<li>\r\n		Upload it to the following link with the total hours and other required details:&nbsp;<a href=\"https://app.smartsheet.com/b/form/5ed35b3160c043679502566d74ff12d8\">https://app.smartsheet.com/b/form/5ed35b3160c043679502566d74ff12d8</a></li>\r\n</ol>', '2024-10-26 21:20:35', '2024-11-30 22:50:18'),
